/// Strip TOML comments (from '#' to end of line) while respecting
/// basic string literals.
fn strip_comment(line : String) -> String {
  let mut buf = StringBuilder::new()
  let mut in_string = false
  let mut escape = false
  let mut i = 0
  while i < line.length() {
    let c = line[i]
    if escape {
      buf.write_char(c)
      escape = false
    } else if c == '\\' && in_string {
      buf.write_char(c)
      escape = true
    } else if c == '"' {
      buf.write_char(c)
      in_string = !in_string
    } else if c == '#' && !in_string {
      // Comment starts; stop here
      return buf.to_string()
    } else {
      buf.write_char(c)
    }
    i += 1
  }
  buf.to_string()
}

/// Parse a TOML value string into a Json value.
fn parse_value(s : String, lineno : Int) -> Json!TomlError {
  let trimmed = s.trim()
  if trimmed.length() == 0 {
    raise TomlError("line \{lineno}: empty value")
  }

  match trimmed.char_at(0) {
    Some('"') => {
      // String
      let s_parsed = parse_string(trimmed, lineno)?
      Json::string(s_parsed)
    }
    Some('t') | Some('f') => {
      // Boolean
      if trimmed == "true" {
        Json::boolean(true)
      } else if trimmed == "false" {
        Json::boolean(false)
      } else {
        raise TomlError("line \{lineno}: invalid boolean '\{trimmed}'")
      }
    }
    Some('[') => {
      // Array
      parse_array(trimmed, lineno)?
    }
    Some(c) if c.is_digit() || c == '+' || c == '-' => {
      // Integer
      let n = @string.parse_int(trimmed) catch {
        _ => raise TomlError("line \{lineno}: invalid integer '\{trimmed}'")
      }
      Json::number(n.to_double(), repr = trimmed)
    }
    _ => {
      raise TomlError("line \{lineno}: unexpected value '\{trimmed}'")
    }
  }
}

/// Parse a TOML basic string (including escape sequences).
fn parse_string(s : String, lineno : Int) -> String!TomlError {
  // s should start and end with double quotes
  guard s.length() >= 2 && s.char_at(0) == Some('"') else {
    raise TomlError("line \{lineno}: invalid string literal '\{s}'")
  }
  // Find closing quote (not escaped)
  let mut buf = StringBuilder::new()
  let mut i = 1
  let mut escape = false
  while i < s.length() {
    let c = s[i]
    if escape {
      match c {
        '"' => buf.write_char('"')
        '\\' => buf.write_char('\\')
        'n' => buf.write_char('\n')
        't' => buf.write_char('\t')
        _ => raise TomlError("line \{lineno}: invalid escape '\\\{c}'")
      }
      escape = false
    } else if c == '\\' {
      escape = true
    } else if c == '"' {
      // End of string
      return buf.to_string()
    } else {
      buf.write_char(c)
    }
    i += 1
  }
  raise TomlError("line \{lineno}: unclosed string literal")
}

/// Parse a TOML array of scalar values.
fn parse_array(s : String, lineno : Int) -> Json!TomlError {
  guard s.length() >= 2 && s.char_at(0) == Some('[') else {
    raise TomlError("line \{lineno}: invalid array '\{s}'")
  }
  // Find matching close bracket (simple: scan for ']' not inside a string)
  let content_buf = StringBuilder::new()
  let mut depth = 1
  let mut in_string = false
  let mut escape = false
  let mut i = 1
  while i < s.length() {
    let c = s[i]
    if escape {
      content_buf.write_char(c)
      escape = false
    } else if c == '\\' && in_string {
      content_buf.write_char(c)
      escape = true
    } else if c == '"' {
      content_buf.write_char(c)
      in_string = !in_string
    } else if c == '[' && !in_string {
      content_buf.write_char(c)
      depth += 1
    } else if c == ']' && !in_string {
      depth -= 1
      if depth == 0 {
        // End of array
        let content = content_buf.to_string()
        return parse_array_elements(content, lineno)
      }
      content_buf.write_char(c)
    } else {
      content_buf.write_char(c)
    }
    i += 1
  }
  raise TomlError("line \{lineno}: unclosed array")
}

/// Parse comma-separated elements from the inner content of an array.
fn parse_array_elements(content : String, lineno : Int) -> Json!TomlError {
  let trimmed = content.trim()
  if trimmed.length() == 0 {
    return Json::array([])
  }

  let mut elements : Array[Json] = []
  // Split by commas, respecting strings
  let mut current = StringBuilder::new()
  let mut in_string = false
  let mut escape = false
  let mut i = 0
  while i < trimmed.length() {
    let c = trimmed[i]
    if escape {
      current.write_char(c)
      escape = false
    } else if c == '\\' && in_string {
      current.write_char(c)
      escape = true
    } else if c == '"' {
      current.write_char(c)
      in_string = !in_string
    } else if c == ',' && !in_string {
      // End of element
      let elem_str = current.to_string().trim()
      if elem_str.length() > 0 {
        elements.push(parse_value(elem_str, lineno)?)
      }
      current = StringBuilder::new()
    } else {
      current.write_char(c)
    }
    i += 1
  }
  // Last element
  let elem_str = current.to_string().trim()
  if elem_str.length() > 0 {
    elements.push(parse_value(elem_str, lineno)?)
  }

  Json::array(elements)
}

/// Build a nested JSON object from a flat map of dot-separated keys.
fn build_nested_json(pairs : Map[String, Json]) -> Json {  
  let root : Map[String, Json] = Map::new()
  for key, value in pairs {
    let parts = key.split(".")
    set_nested(root, parts, 0, value)
  }
  Json::object(root)
}

/// Recursively set a value in a nested map structure.
fn set_nested(map : Map[String, Json], parts : Array[StringView], idx : Int, value : Json) {
  let key = parts[idx].to_owned()
  if idx == parts.length() - 1 {
    map[key] = value
  } else {
    // Navigate or create sub-map
    let sub_map = if map.contains(key) {
      match map[key] {
        Json::Object(m) => m
        _ => {
          // Key exists but isn't an object; replace with new object
          let m : Map[String, Json] = Map::new()
          map[key] = Json::object(m)
          m
        }
      }
    } else {
      let m : Map[String, Json] = Map::new()
      map[key] = Json::object(m)
      m
    }
    set_nested(sub_map, parts, idx + 1, value)
  }
}
