{"content": "/// TOML to JSON converter — reads TOML from a file or stdin and outputs JSON.

async fn main {
  let args = @sys.get_cli_args()
  let use_stdin = args.length() > 1 && args[1] == "--stdin"

  let toml_text = if use_stdin {
    @stdio.stdin.read_all().text()
  } else if args.length() > 1 {
    let path = args[1]
    @fs.read_file(path).text() catch {
      error => {
        @stdio.stderr.write("error: \{error}\n")
        @sys.exit(1)
        return
      }
    }
  } else {
    @stdio.stderr.write("usage: tomljson [--stdin | <path>]\n")
    @sys.exit(1)
    return
  }

  let json = @toml.parse(toml_text) catch {
    error => {
      @stdio.stderr.write("error: \{error}\n")
      @sys.exit(1)
      return
    }
  }

  @stdio.stdout.write(json.stringify())
  @stdio.stdout.write("\n")
}
", "path": "/private/tmp/prompt_demos/runs_flash-demos/workspaces/05/cmd/tomljson/main.mbt"}

