// Tests for the TOML parser library.

test "parse simple key-value" {
  let toml = "name = \"hello\""
  let json = parse(toml)
  match json {
    Json::Object(m) => {
      match m["name"] {
        Json::String(s) => assert_eq(s, "hello")
        _ => fail("expected string")
      }
    }
    _ => fail("expected object")
  }
}

test "parse integer and boolean" {
  let toml = #|count = 42
#|enabled = true
  let json = parse(toml)
  match json {
    Json::Object(m) => {
      match m["count"] {
        Json::Number(n, ..) => assert_eq(n, 42.0)
        _ => fail("expected number")
      }
      match m["enabled"] {
        Json::True => ()
        _ => fail("expected true")
      }
    }
    _ => fail("expected object")
  }
}

test "parse table" {
  let toml = #|[owner]
#|name = \"Alice\"
  let json = parse(toml)
  match json {
    Json::Object(m) => {
      match m["owner"] {
        Json::Object(om) => {
          match om["name"] {
            Json::String(s) => assert_eq(s, "Alice")
            _ => fail("expected string")
          }
        }
        _ => fail("expected nested object")
      }
    }
    _ => fail("expected object")
  }
}

test "parse nested table" {
  let toml = #|[database.settings]
#|port = 5432
  let json = parse(toml)
  match json {
    Json::Object(m) => {
      match m["database"] {
        Json::Object(dm) => {
          match dm["settings"] {
            Json::Object(sm) => {
              match sm["port"] {
                Json::Number(n, ..) => assert_eq(n, 5432.0)
                _ => fail("expected number")
              }
            }
            _ => fail("expected settings object")
          }
        }
        _ => fail("expected database object")
      }
    }
    _ => fail("expected object")
  }
}

test "parse dotted keys" {
  let toml = "a.b.c = 1"
  let json = parse(toml)
  match json {
    Json::Object(m) => {
      match m["a"] {
        Json::Object(am) => {
          match am["b"] {
            Json::Object(bm) => {
              match bm["c"] {
                Json::Number(n, ..) => assert_eq(n, 1.0)
                _ => fail("expected number")
              }
            }
            _ => fail("expected b object")
          }
        }
        _ => fail("expected a object")
      }
    }
    _ => fail("expected object")
  }
}

test "parse array" {
  let toml = "values = [1, 2, 3]"
  let json = parse(toml)
  match json {
    Json::Object(m) => {
      match m["values"] {
        Json::Array(a) => {
          assert_eq(a.length(), 3)
        }
        _ => fail("expected array")
      }
    }
    _ => fail("expected object")
  }
}

test "parse array of booleans" {
  let toml = "flags = [true, false, true]"
  let json = parse(toml)
  match json {
    Json::Object(_) => ()
    _ => fail("expected object")
  }
}

test "parse empty array" {
  let toml = "items = []"
  let json = parse(toml)
  match json {
    Json::Object(m) => {
      match m["items"] {
        Json::Array(a) => assert_eq(a.length(), 0)
        _ => fail("expected array")
      }
    }
    _ => fail("expected object")
  }
}

test "parse string escapes" {
  let toml = "text = \"hello\\nworld\\ttab\""
  let json = parse(toml)
  match json {
    Json::Object(m) => {
      match m["text"] {
        Json::String(s) => {
          assert_eq(s, "hello\nworld\ttab")
        }
        _ => fail("expected string")
      }
    }
    _ => fail("expected object")
  }
}

test "parse string with backslash and quote escapes" {
  let toml = "text = \"quote: \\\"hello\\\" back: \\\\\""
  let json = parse(toml)
  match json {
    Json::Object(m) => {
      match m["text"] {
        Json::String(s) => {
          assert_eq(s, "quote: \"hello\" back: \\")
        }
        _ => fail("expected string")
      }
    }
    _ => fail("expected object")
  }
}

test "duplicate key error" {
  let toml = "key = 1\nkey = 2"
  try {
    let _ = parse(toml)
    assert_true(false)
  } catch {
    TomlError(msg) => assert_true(msg.contains("duplicate key"))
    _ => assert_true(false)
  } noraise {
    _ => assert_true(false)
  }
}

