    _ => assert_true(false)
  } noraise {
    _ => assert_true(false)
  }
}

test "parse comment and blank lines" {
  let toml = "# this is a comment\n\nkey = \"value\"\n  # indented comment"
  let json = parse(toml)
  match json {
    Json::Object(m) => {
      match m["key"] {
        Json::String(s) => assert_eq(s, "value")
        _ => fail("expected string")
      }
    }
    _ => fail("expected object")
  }
}

test "parse comment in string does not comment out" {
  let toml = "key = \"val#ue\""
  let json = parse(toml)
  match json {
    Json::Object(m) => {
      match m["key"] {
        Json::String(s) => assert_eq(s, "val#ue")
        _ => fail("expected string")
      }
    }
    _ => fail("expected object")
  }
}

test "parse negative integer" {
  let toml = "temp = -5"
  let json = parse(toml)
  match json {
    Json::Object(m) => {
      match m["temp"] {
        Json::Number(n, ..) => assert_eq(n, -5.0)
